update public.learning_paths
set
  title = 'Sensation and Perception',
  goal = 'Sensation and Perception',
  summary = 'Sensation and Perception frames perception as active information processing that transforms physical energy into meaningful experience and action. Students learn how perceptual experience is measured, modeled, and separated from bias, noise, and decision criteria, and how receptors, neurons, circuits, and cortical maps encode sensory information. The course studies vision, audition, body senses, chemical senses, attention, top-down processing, multisensory integration, and constancy; illusions, atypical perception, lifespan change, and culture reveal how perceptual systems work, and students synthesize perception through computational models, applied domains, ethical issues, and a final demonstration or research design.',
  data = $senpjson${"slug": "sensation-and-perception", "title": "Sensation and Perception", "description": "Sensation and Perception frames perception as active information processing that transforms physical energy into meaningful experience and action. Students learn how perceptual experience is measured, modeled, and separated from bias, noise, and decision criteria, and how receptors, neurons, circuits, and cortical maps encode sensory information. The course studies vision, audition, body senses, chemical senses, attention, top-down processing, multisensory integration, and constancy; illusions, atypical perception, lifespan change, and culture reveal how perceptual systems work, and students synthesize perception through computational models, applied domains, ethical issues, and a final demonstration or research design.", "topics": [{"id": "1984ea16-6f79-4af1-a7f4-b913b626fe28", "type": "topic", "title": "Foundations of Sensation, Perception, and Perceptual Science", "description": "Frame perception as active information processing that transforms physical energy into meaningful experience and action.", "children": [{"id": "61db626d-8541-4726-9c07-bafaec4a4618", "type": "subtopic", "title": "Sensation vs Perception", "children": [{"id": "9c7d4dd1-c320-4e04-850c-67c3b6d85f4b", "type": "concept", "title": "Stimulus energy"}, {"id": "fd1f9296-428d-45c9-8053-aa668487e556", "type": "concept", "title": "Sensory registration"}, {"id": "a49a27ee-4f09-43b7-b377-5b55ff392c9f", "type": "concept", "title": "Perceptual organization"}, {"id": "3f2857c1-3784-4f71-877f-730e3e279328", "type": "concept", "title": "Perception-action loops"}], "description": "This subtopic clarifies the difference between detecting physical energy and interpreting it as meaningful experience."}, {"id": "75001573-c9fb-477b-bfb6-f502aea813a5", "type": "subtopic", "title": "Perception as Construction", "children": [{"id": "57afc6db-08a2-4d10-896d-bdebcca214c2", "type": "concept", "title": "Ambiguity"}, {"id": "5986cff1-41e0-4d8b-82d5-96f6033b644f", "type": "concept", "title": "Inference"}, {"id": "419cc8a3-98a8-4203-90ba-e688b41f8825", "type": "concept", "title": "Context effects"}, {"id": "5e003f61-5c99-47e3-bebc-22fef70b5a3b", "type": "concept", "title": "Perceptual constancy"}], "description": "Perception is not a passive copy of the world; it is an active, adaptive interpretation of incomplete information."}, {"id": "0c62d78e-398d-4787-b130-590440c09d03", "type": "subtopic", "title": "Methods and Levels of Explanation", "children": [{"id": "aae0f0a2-8bad-4a87-990b-cf003f840fdb", "type": "concept", "title": "Behavioral experiments"}, {"id": "77dbaa00-caca-48e0-8383-cae25599c68e", "type": "concept", "title": "Neuroscience methods"}, {"id": "070780c0-88c0-4a30-bd2b-0c0e81913c65", "type": "concept", "title": "Computational models"}, {"id": "c590312f-536f-4777-8150-b56cc030b660", "type": "concept", "title": "Ecological validity"}], "description": "Students learn how perceptual science links behavior, brain systems, computation, and real-world function."}]}, {"id": "8a64b1eb-9abe-453b-ab72-d1dc96aa58cf", "type": "topic", "title": "Psychophysics, Measurement, and Signal Detection Theory", "description": "Learn how perceptual experience is measured, modeled, and separated from bias, noise, and decision criteria.", "children": [{"id": "59d7e8cf-8d16-4e31-b1b0-4710b5e2605f", "type": "subtopic", "title": "Classical Psychophysics", "children": [{"id": "62fdebcc-d646-4908-8af3-43bcb988ca7b", "type": "concept", "title": "Absolute threshold"}, {"id": "ac455d5a-9671-4dd7-b6ca-d3395a801144", "type": "concept", "title": "Difference threshold"}, {"id": "441efcc2-4a09-4991-b2ed-d270038ab64c", "type": "concept", "title": "Weber's law"}, {"id": "f9ec08c5-2600-44a4-b2c3-4533b9671569", "type": "concept", "title": "Fechner and Stevens scaling"}], "description": "Psychophysics gives tools for relating physical stimulus intensity to subjective experience."}, {"id": "6a21c845-09c1-4189-8dbe-e048d8d8d242", "type": "subtopic", "title": "Signal Detection Theory", "children": [{"id": "525997df-c5e4-4818-b163-96ac451b4408", "type": "concept", "title": "Hits and false alarms"}, {"id": "ad30b41b-cc2e-4084-9e22-2616b5b8efbb", "type": "concept", "title": "Sensitivity"}, {"id": "39bb032b-bfdc-4abf-a973-8db52989040a", "type": "concept", "title": "Decision criterion"}, {"id": "d865a41d-5d98-45b8-a520-beb4720690ef", "type": "concept", "title": "Receiver operating characteristic"}], "description": "Signal detection separates sensory sensitivity from response bias, making perception measurable under uncertainty."}, {"id": "42607b63-24dc-495a-91e7-92665717aa60", "type": "subtopic", "title": "Modern Measurement Designs", "children": [{"id": "f6bc8781-1bf8-4715-a3b3-2000f9c2e777", "type": "concept", "title": "Staircase procedures"}, {"id": "dab06d58-c33b-49b7-ae57-a1186e9a59ac", "type": "concept", "title": "Two-alternative forced choice"}, {"id": "0854e262-5394-41ac-9b7d-95a9b10f12a3", "type": "concept", "title": "Reaction-time distributions"}, {"id": "1fda054e-8d0a-42a9-98b0-d3173433e469", "type": "concept", "title": "Reliability and validity"}], "description": "Modern perception studies use adaptive tasks, forced choice, reaction time, and modeling to improve inference."}]}, {"id": "b26866e1-290d-44b7-93b2-ef0d10762635", "type": "topic", "title": "Neural Coding, Sensory Transduction, and Brain Pathways", "description": "Understand how receptors, neurons, circuits, and cortical maps encode sensory information.", "children": [{"id": "349f6ba0-87de-419e-87ac-4256936e6d5e", "type": "subtopic", "title": "Sensory Transduction", "children": [{"id": "0d96e66c-b8fe-4d87-b84a-890903faa96b", "type": "concept", "title": "Receptor cells"}, {"id": "7e9685c3-b946-4304-b527-26ca0ca8bf49", "type": "concept", "title": "Action potentials"}, {"id": "2efc1308-fda1-4f92-b7ee-8d80031000a2", "type": "concept", "title": "Adaptation"}, {"id": "d953d216-541e-460d-b402-ff8fb8e86ddd", "type": "concept", "title": "Dynamic range"}], "description": "Transduction explains how light, pressure, chemicals, temperature, and vibration become neural signals."}, {"id": "85518c58-a44c-4323-bf68-525ef42efccb", "type": "subtopic", "title": "Neural Coding", "children": [{"id": "ae139f2b-b95a-4086-88ef-829f5d4c22d1", "type": "concept", "title": "Rate coding"}, {"id": "79c25d5c-4cd3-49f2-8ba8-18326b45caa0", "type": "concept", "title": "Temporal coding"}, {"id": "1197865b-2aca-4f03-a915-e829449bbffb", "type": "concept", "title": "Population coding"}, {"id": "53f4730d-cf66-4664-aead-a3eceac72a87", "type": "concept", "title": "Labeled lines"}], "description": "Neural coding asks how patterns of activity represent intensity, location, identity, and change."}, {"id": "c4054814-4765-4ffe-80fd-e249e1644f01", "type": "subtopic", "title": "Pathways and Cortical Maps", "children": [{"id": "bb635335-663b-4651-b88c-bd0c29a7dc9a", "type": "concept", "title": "Receptive fields"}, {"id": "c29a3c35-d66e-4dd4-91cd-0b41ebf90f17", "type": "concept", "title": "Topographic maps"}, {"id": "a045dadc-3998-41e6-9259-a235ea6fbe38", "type": "concept", "title": "Thalamic relays"}, {"id": "53faf378-3350-4b12-b67d-dc8ae93b2ad1", "type": "concept", "title": "Cortical hierarchy"}], "description": "Sensory pathways preserve, transform, and integrate information through organized neural maps."}]}, {"id": "6a727d3f-a40a-49db-ba03-fb77e4744e4c", "type": "topic", "title": "Visual System Anatomy, Retina, and Early Vision", "description": "Study the eye, retina, thalamus, and early visual cortex as the entry point to visual perception.", "children": [{"id": "93545355-81d5-4b25-8c77-9e10cb68177d", "type": "subtopic", "title": "Eye and Optics", "children": [{"id": "655201a9-1267-45a9-a99b-5ff6e643f07c", "type": "concept", "title": "Cornea and lens"}, {"id": "dd757ac1-598f-4d15-9e17-dfdda0f5b112", "type": "concept", "title": "Accommodation"}, {"id": "023f51d0-2b88-46d5-a6cf-3110773da93c", "type": "concept", "title": "Pupil and aperture"}, {"id": "9624830b-b302-4b2d-b826-1543166c8797", "type": "concept", "title": "Acuity and refractive error"}], "description": "The optics of the eye determine the quality and limits of the image that reaches the retina."}, {"id": "4419d1af-7c07-4a7b-848d-44717758febd", "type": "subtopic", "title": "Retinal Processing", "children": [{"id": "e37e187c-5161-49cb-b510-ec51bc0d8964", "type": "concept", "title": "Rods and cones"}, {"id": "c75ce820-6cd8-4280-8c10-aefc7a95c7f8", "type": "concept", "title": "Bipolar cells"}, {"id": "386939b2-5499-40f8-822c-86f935615027", "type": "concept", "title": "Ganglion cells"}, {"id": "41b595ee-696f-4204-becf-1ce5074e95db", "type": "concept", "title": "Lateral inhibition"}], "description": "The retina is an active neural processor, not just a camera surface."}, {"id": "d6017f6e-e2c9-4224-9030-6891fd5d2fce", "type": "subtopic", "title": "Early Visual Cortex", "children": [{"id": "c89560f9-ed9e-4d14-8568-36530fab0ebe", "type": "concept", "title": "LGN"}, {"id": "03740e9c-0d49-4ba3-8edd-36a6e5a65b08", "type": "concept", "title": "V1"}, {"id": "515e38d4-b50c-4426-a977-cf79939b5991", "type": "concept", "title": "Orientation selectivity"}, {"id": "7e071183-5ca7-4675-8875-5ed2ed82553f", "type": "concept", "title": "Retinotopy"}], "description": "Early visual cortex organizes visual information into maps and features that support later perception."}]}, {"id": "fbdf37aa-1173-4798-9214-f85e70113375", "type": "topic", "title": "Color, Lightness, Form, and Object Perception", "description": "Explain how the visual system extracts color, edges, shapes, objects, and stable surfaces from changing input.", "children": [{"id": "82347381-7077-4601-be5f-5654b0fae8ae", "type": "subtopic", "title": "Color Perception", "children": [{"id": "eb069398-69ce-43f5-9949-f3ed7abbd0df", "type": "concept", "title": "Trichromatic theory"}, {"id": "82eff610-42bd-43ed-a542-f1eed4eca2e9", "type": "concept", "title": "Opponent processes"}, {"id": "59ee3392-043f-4b98-b310-8be2e1808f21", "type": "concept", "title": "Color constancy"}, {"id": "3b2c27c3-2e91-4549-9a6d-2532706a1d92", "type": "concept", "title": "Color deficiency"}], "description": "Color perception shows how the brain interprets wavelength information under changing illumination."}, {"id": "13b39303-574d-4719-9a1f-a487f9a2865b", "type": "subtopic", "title": "Lightness and Surface Perception", "children": [{"id": "efe90949-9dbb-41e0-94c6-7b4002976d56", "type": "concept", "title": "Simultaneous contrast"}, {"id": "55b2aea0-9d34-46b0-8917-e533bf126fe3", "type": "concept", "title": "Illumination vs reflectance"}, {"id": "2ada552a-1a45-4f8f-9a6d-02e5d72c8260", "type": "concept", "title": "Shadows"}, {"id": "43e6f97d-b922-44db-92d9-ab656377bb2c", "type": "concept", "title": "Brightness illusions"}], "description": "Lightness perception depends on context, contrast, shadows, and assumptions about surfaces."}, {"id": "fe2196e6-1051-46a7-8831-831ce4f19e0a", "type": "subtopic", "title": "Form and Object Recognition", "children": [{"id": "ee30624e-f222-49ac-93f2-2dc7f9a7b2a1", "type": "concept", "title": "Edges and contours"}, {"id": "0609dec1-e049-4080-8247-ece0c9b99329", "type": "concept", "title": "Gestalt grouping"}, {"id": "81b79d4d-ade4-48e1-a32d-e08dbfdf2dd1", "type": "concept", "title": "Ventral stream"}, {"id": "26da2397-46fa-4c04-a619-e35ab9def18e", "type": "concept", "title": "Viewpoint and invariance"}], "description": "Object perception turns edges and features into stable categories and identities."}]}, {"id": "547f086f-a8fb-4f00-a50e-9be59ceadd0c", "type": "topic", "title": "Depth, Size, Space, and Scene Perception", "description": "Analyze how observers perceive three-dimensional layout, distance, scale, scenes, and navigable environments.", "children": [{"id": "bbcdeed8-998d-4fff-aac2-b936ecb1bf65", "type": "subtopic", "title": "Depth Cues", "children": [{"id": "9048fbfb-3cd6-40f7-abf9-218d16243266", "type": "concept", "title": "Binocular disparity"}, {"id": "4078fbde-b7fe-4485-b305-d7ccf50f6985", "type": "concept", "title": "Convergence"}, {"id": "65858981-cee7-4a7b-a0f3-dc1de37ff87c", "type": "concept", "title": "Motion parallax"}, {"id": "584baed4-e8f2-40e5-a681-753a43ba69ca", "type": "concept", "title": "Pictorial cues"}], "description": "Depth perception integrates many cues to infer 3D layout from 2D retinal images."}, {"id": "116c1bd2-0fc4-407e-9634-7b09882ed9ff", "type": "subtopic", "title": "Size and Space Constancy", "children": [{"id": "64dbee0f-cceb-4eb9-b245-6cf47682ab60", "type": "concept", "title": "Size constancy"}, {"id": "e849b866-854c-4527-b2a7-630681854188", "type": "concept", "title": "Shape constancy"}, {"id": "cad842c0-5e38-45db-9a9c-88878e01e084", "type": "concept", "title": "Ames room"}, {"id": "2cf441d5-d548-4235-a134-f94731637606", "type": "concept", "title": "Distance scaling"}], "description": "Perception keeps size, shape, and layout stable despite changes in viewing conditions."}, {"id": "dca4b5b1-050d-4127-bd75-0fd9fdbb2eda", "type": "subtopic", "title": "Scene and Navigation Perception", "children": [{"id": "a2610569-16bb-4368-a6ef-a50a5870eaf9", "type": "concept", "title": "Scene gist"}, {"id": "26ec1793-a162-4559-9e60-e1a5ca8de5b4", "type": "concept", "title": "Spatial layout"}, {"id": "61e8af35-4837-4594-ada1-9c4391050f22", "type": "concept", "title": "Landmarks"}, {"id": "4a261eb8-f9f4-4b99-a391-3282b76b3960", "type": "concept", "title": "Place and boundary processing"}], "description": "Scene perception supports rapid understanding of places, routes, and affordances."}]}, {"id": "ea1d80be-cafa-43e9-8e93-52dc28dc2075", "type": "topic", "title": "Motion, Event Perception, and Perception for Action", "description": "Explore how motion and action systems support tracking, prediction, coordination, and interaction with the world.", "children": [{"id": "3db4d4da-9cc0-4e97-a042-f8414c499e23", "type": "subtopic", "title": "Motion Detection", "children": [{"id": "d45686f2-cfb2-409f-91be-d383b8d58dae", "type": "concept", "title": "Apparent motion"}, {"id": "936bab0a-58bd-4517-b455-a5712874bf23", "type": "concept", "title": "Optic flow"}, {"id": "e458c8d2-b14a-45f7-8adc-329fed7c0f01", "type": "concept", "title": "Motion aftereffect"}, {"id": "f9d92641-bcc8-44a8-91ac-1159a45712af", "type": "concept", "title": "MT/V5"}], "description": "Motion perception helps organisms track objects, navigate, and predict what will happen next."}, {"id": "6100f4b3-a457-46f5-9dc0-3c72c7e5437d", "type": "subtopic", "title": "Event Perception", "children": [{"id": "0aa2e944-185f-42f1-a9d5-948851512fd3", "type": "concept", "title": "Biological motion"}, {"id": "924ff11f-0aea-4027-9085-c07bd5c76cec", "type": "concept", "title": "Causality perception"}, {"id": "5f7ec938-ac33-43a3-bf7f-c77dd0974144", "type": "concept", "title": "Temporal grouping"}, {"id": "1a8ca279-14b5-4684-9463-fc30966a13ba", "type": "concept", "title": "Prediction"}], "description": "People perceive structured events, causal relations, and action sequences rather than isolated frames."}, {"id": "e58249e3-ed9e-4a1e-b4ff-37ede45207eb", "type": "subtopic", "title": "Perception for Action", "children": [{"id": "353691f4-48e6-40c5-9013-287e9083f8d7", "type": "concept", "title": "Dorsal stream"}, {"id": "13afcdfb-e41c-495b-a283-7ee72bb24e9a", "type": "concept", "title": "Affordances"}, {"id": "6352fa28-91ef-474b-903c-b710bbcb1490", "type": "concept", "title": "Visuomotor control"}, {"id": "b781b900-2e4c-4a35-ac1b-f545fac5e527", "type": "concept", "title": "Online correction"}], "description": "Action systems use perception for reaching, grasping, locomotion, and coordination."}]}, {"id": "0762c407-8d3e-49e8-8fc8-04f7a3205601", "type": "topic", "title": "Audition, Speech, Music, and Sound Localization", "description": "Study how the auditory system converts sound waves into pitch, loudness, location, speech, music, and auditory scenes.", "children": [{"id": "63d3b870-0e17-47c3-8b5d-e842eddc5c6e", "type": "subtopic", "title": "Auditory Transduction", "children": [{"id": "4ce816ad-ae19-44ce-9180-3bbb54bc7afe", "type": "concept", "title": "Outer and middle ear"}, {"id": "ed6db710-56aa-4402-a859-7e595810a7e7", "type": "concept", "title": "Cochlea"}, {"id": "b7789561-ebe5-4709-b676-58af12581109", "type": "concept", "title": "Hair cells"}, {"id": "3917b124-8b07-4b31-acb5-6a8d732fd853", "type": "concept", "title": "Tonotopy"}], "description": "Hearing begins with mechanical energy transformed into neural activity in the cochlea."}, {"id": "b8ac4a13-11f4-4829-9eb4-7e7d6e1555f8", "type": "subtopic", "title": "Auditory Perception", "children": [{"id": "e168807e-407a-474d-975d-4d3ca912408f", "type": "concept", "title": "Frequency and pitch"}, {"id": "0e808824-89f8-4071-8569-808115824569", "type": "concept", "title": "Amplitude and loudness"}, {"id": "a241295b-c53a-4ff9-aeb6-6d1cfc24f342", "type": "concept", "title": "Timbre"}, {"id": "67937792-78e2-47df-a0b0-edfa54b89f0b", "type": "concept", "title": "Auditory scene analysis"}], "description": "Auditory perception organizes sound into pitch, loudness, timbre, rhythm, and sound sources."}, {"id": "68bce52b-5201-4e51-b1fc-931cec4788c3", "type": "subtopic", "title": "Speech, Music, and Localization", "children": [{"id": "3c5bd43d-3501-499c-964e-06c4cc5cec2f", "type": "concept", "title": "Phoneme perception"}, {"id": "67d3557d-1b50-47c0-93c5-a9601615895e", "type": "concept", "title": "Categorical perception"}, {"id": "2f777af7-5fcd-49df-9137-fde4e7553473", "type": "concept", "title": "Interaural time and level differences"}, {"id": "fcd62b05-ef70-44b2-a7bd-bdad9c88c4be", "type": "concept", "title": "Music and rhythm"}], "description": "Complex auditory perception supports communication, music, and orientation in space."}]}, {"id": "d4d24288-9528-4b4f-b551-8f459865d773", "type": "topic", "title": "Somatosensation, Proprioception, Vestibular Sense, and Pain", "description": "Connect body senses to touch, balance, movement, body ownership, pain, and embodied perception.", "children": [{"id": "53620a9b-83a6-4d0d-bd47-70c74a7e3402", "type": "subtopic", "title": "Touch and Somatosensory Pathways", "children": [{"id": "35bcd905-caaf-4004-8138-4c3e2df86d18", "type": "concept", "title": "Mechanoreceptors"}, {"id": "f9e1b74c-10dc-4d4f-8061-8b31bc010bc5", "type": "concept", "title": "Thermoreceptors"}, {"id": "3dd85423-e0e8-4192-befe-8d590222e57b", "type": "concept", "title": "Somatotopy"}, {"id": "5cf8c18d-33b1-450d-839f-30f831eebcff", "type": "concept", "title": "Two-point discrimination"}], "description": "Touch links the body surface to cortical maps for texture, pressure, vibration, and temperature."}, {"id": "2edf04f6-0aad-45b7-b695-0a61d45a5534", "type": "subtopic", "title": "Body Position and Balance", "children": [{"id": "ab8aca80-a655-48ee-b8db-909991a9d0e8", "type": "concept", "title": "Muscle spindles"}, {"id": "010e3e53-1cc9-4099-aeb8-0f90a3f55cb6", "type": "concept", "title": "Joint receptors"}, {"id": "eb8ba8db-260d-4acd-9a48-f46f26a2b0c7", "type": "concept", "title": "Semicircular canals"}, {"id": "89ede6b3-60ac-420a-8d27-4c2614386252", "type": "concept", "title": "Otolith organs"}], "description": "Proprioception and vestibular processing support posture, movement, balance, and body awareness."}, {"id": "c73aeba8-9ddc-4cef-b3de-41b6efc66e3b", "type": "subtopic", "title": "Pain and Body Ownership", "children": [{"id": "514c1214-6f29-41c0-bb31-35730b2c200e", "type": "concept", "title": "Nociception"}, {"id": "df07e252-bc4d-41fc-8db9-7465c4555c1f", "type": "concept", "title": "Gate control"}, {"id": "490a3804-9140-43f7-94c7-c0ff383779f0", "type": "concept", "title": "Placebo and expectation"}, {"id": "44b17dbb-534e-40bd-bde2-5c56f9b95940", "type": "concept", "title": "Rubber hand illusion"}], "description": "Pain is both sensory and affective, and body ownership reveals how the brain constructs the bodily self."}]}, {"id": "94d0e42b-a660-41bd-ab27-b44710db57f2", "type": "topic", "title": "Taste, Smell, Flavor, and Chemical Senses", "description": "Understand chemical sensing as an integrated system for nutrition, emotion, memory, danger detection, and culture.", "children": [{"id": "7aac28b7-deed-43ed-84d5-38d512e6bf63", "type": "subtopic", "title": "Taste and Flavor", "children": [{"id": "9185de8f-e6d6-40b0-a041-87f9cb649005", "type": "concept", "title": "Basic tastes"}, {"id": "c3e19b05-4e34-4048-966c-6bea0ec386ba", "type": "concept", "title": "Taste receptors"}, {"id": "9cf6cdf7-ee5f-444f-98d0-35fc30f81908", "type": "concept", "title": "Retronasal olfaction"}, {"id": "09a8da82-b759-44d7-a4e2-b6bcd93177bf", "type": "concept", "title": "Texture and temperature"}], "description": "Flavor is a multisensory construction combining taste, smell, texture, temperature, and expectation."}, {"id": "56d254bf-6247-4cb4-8c2b-2228b072ea87", "type": "subtopic", "title": "Olfaction", "children": [{"id": "c3af44a2-69f8-4678-b2f6-d2c5590a839f", "type": "concept", "title": "Odor receptors"}, {"id": "0a44600e-6882-4a3f-ba0d-147fd7c3a1f6", "type": "concept", "title": "Olfactory bulb"}, {"id": "6994d5fb-4b91-44f7-b43e-69a163df2a22", "type": "concept", "title": "Odor identification"}, {"id": "3faff115-7668-40e0-ae5b-0e0476ec01d5", "type": "concept", "title": "Anosmia and parosmia"}], "description": "Smell has strong links to memory, emotion, threat detection, and social context."}, {"id": "91481682-1bbb-4e2b-b151-ab1c85930e5c", "type": "subtopic", "title": "Chemical Senses in Life", "children": [{"id": "babda53c-3eba-4a4d-9f52-0a7c1b537c1b", "type": "concept", "title": "Food preference"}, {"id": "4f6b5b5f-25ee-4da2-98ef-f74a8918e0be", "type": "concept", "title": "Disgust"}, {"id": "1ccacd0c-d4c8-4ea3-ab38-0931acdf3805", "type": "concept", "title": "Pheromone debates"}, {"id": "7171f1f7-763e-43ba-b35d-a27b7251e6d1", "type": "concept", "title": "Clinical smell and taste loss"}], "description": "Chemical senses matter for nutrition, culture, pleasure, disgust, safety, and health."}]}, {"id": "63d17b37-6b67-48eb-8414-266e404108dd", "type": "topic", "title": "Attention, Awareness, and Perceptual Selection", "description": "Learn how attention prioritizes sensory information and shapes conscious perceptual experience.", "children": [{"id": "391065fa-8fa6-42c0-aefb-4217eaa9de46", "type": "subtopic", "title": "Selective Attention", "children": [{"id": "cd78b52a-0cce-42cc-acf9-256c066c499f", "type": "concept", "title": "Spatial attention"}, {"id": "99bb8fe1-7e06-46d8-853b-b7735d8df6f1", "type": "concept", "title": "Feature attention"}, {"id": "c1c123fc-8ff7-4ca0-9d62-3385199731d0", "type": "concept", "title": "Object-based attention"}, {"id": "64e95e81-5798-467d-9a3c-4ed403f82502", "type": "concept", "title": "Attentional cueing"}], "description": "Attention prioritizes some information over other information when capacity is limited."}, {"id": "29a91478-7471-4ee6-aaaf-f8d163be1ae6", "type": "subtopic", "title": "Awareness and Inattention", "children": [{"id": "91bf22b5-4e54-4973-b299-0b81dc1f3fc1", "type": "concept", "title": "Inattentional blindness"}, {"id": "153cb235-78b6-46bf-825a-68fd8b991e4b", "type": "concept", "title": "Change blindness"}, {"id": "174b21c9-17a0-4602-95be-7fc0800fbd4f", "type": "concept", "title": "Masking"}, {"id": "7f63d16d-cd83-4419-a880-06ad58a88ed0", "type": "concept", "title": "Subliminal perception"}], "description": "Perception can occur with partial awareness, and salient events can be missed without attention."}, {"id": "3ad2830f-3118-4776-a1eb-dbcf9f79b864", "type": "subtopic", "title": "Attention Networks and Eye Movements", "children": [{"id": "a2a2ac14-d554-4cf3-ae89-51e6b35301fe", "type": "concept", "title": "Dorsal attention network"}, {"id": "02756de3-b8c6-43cd-8030-85a7130818bb", "type": "concept", "title": "Ventral attention network"}, {"id": "b9988fc8-9218-4b74-99c2-d22f91785af7", "type": "concept", "title": "Saccades"}, {"id": "e11a94b1-b173-4ab1-a89b-34667004bcb5", "type": "concept", "title": "Visual search"}], "description": "Attention is coordinated by neural systems and often linked to eye movements and active sampling."}]}, {"id": "d3740d74-3e4f-4f28-978a-815365b71c79", "type": "topic", "title": "Top-Down Processing, Prediction, Context, and Perceptual Learning", "description": "Explain how expectations, memory, context, and expertise shape what people perceive.", "children": [{"id": "cae6109d-8d9f-49fc-b9cf-468886a831c5", "type": "subtopic", "title": "Top-Down Influences", "children": [{"id": "8f838ccd-0936-4b75-b12c-7c0622d816bc", "type": "concept", "title": "Set and expectation"}, {"id": "de4ca98e-e37a-44a8-af64-0b3d92184490", "type": "concept", "title": "Context effects"}, {"id": "c77b00c6-6233-436f-a624-a2c14f0482ec", "type": "concept", "title": "Expertise"}, {"id": "3d550fe4-80ae-4c5e-991c-00621bff42e6", "type": "concept", "title": "Ambiguous figures"}], "description": "Prior knowledge, goals, expectations, and language shape interpretation of sensory input."}, {"id": "d26f635f-b284-4b59-9509-b60bbd98e9b7", "type": "subtopic", "title": "Predictive Processing", "children": [{"id": "cfca5fac-c4a7-4b66-b58a-be653db33a80", "type": "concept", "title": "Prediction error"}, {"id": "fa6e79c7-c763-4093-8e92-56216791f768", "type": "concept", "title": "Bayesian inference"}, {"id": "98e806cc-747c-4cf1-bf4f-68f946991627", "type": "concept", "title": "Hierarchical models"}, {"id": "fcb0cc7b-c36d-495a-9dd4-689512fefd00", "type": "concept", "title": "Priors and likelihoods"}], "description": "Predictive accounts frame perception as the brain's attempt to explain sensory input under uncertainty."}, {"id": "6fc02820-90bf-4470-9df9-e3eeade108fa", "type": "subtopic", "title": "Perceptual Learning", "children": [{"id": "e429b5bc-21fa-4f31-97a7-66757f46cb06", "type": "concept", "title": "Discrimination training"}, {"id": "edfc6a32-2882-4748-a7e6-a5659562f302", "type": "concept", "title": "Expert perception"}, {"id": "15159bfe-92bf-4cc9-b83b-a4afea6fab5e", "type": "concept", "title": "Transfer limits"}, {"id": "3a383525-e22e-41b0-945e-9bfca03f17d8", "type": "concept", "title": "Plasticity"}], "description": "Perceptual systems improve with practice, feedback, and task demands."}]}, {"id": "dde5d54c-a6ed-4bfb-9f5d-4e5ebcbc10e6", "type": "topic", "title": "Multisensory Integration and Perceptual Constancy", "description": "Study how senses combine into stable, coherent perception across changing bodies, contexts, and environments.", "children": [{"id": "30a4fb78-bff5-4cc5-b85f-31692b01e88c", "type": "subtopic", "title": "Multisensory Binding", "children": [{"id": "618b825e-7224-4706-96e4-bd57cb4a8107", "type": "concept", "title": "Temporal binding"}, {"id": "96e6ad22-a096-490a-a454-b4875a80351c", "type": "concept", "title": "Spatial binding"}, {"id": "38bcb575-2318-4968-96ba-d1fc905489a1", "type": "concept", "title": "Cue reliability"}, {"id": "f6c66421-5bef-423e-addf-f75d1c7ffa68", "type": "concept", "title": "Ventriloquism effect"}], "description": "The brain combines information across senses when signals appear to come from the same event."}, {"id": "f4092c8c-3b57-48d7-a87a-35d6e4503a14", "type": "subtopic", "title": "Cross-Modal Perception", "children": [{"id": "bb09a05e-ed44-4650-937d-05c31db14644", "type": "concept", "title": "McGurk effect"}, {"id": "8ddd9898-c517-4f6c-9094-032e5f43c6f4", "type": "concept", "title": "Sound-induced flash illusion"}, {"id": "460514c1-4706-4261-8d40-e5c3c637429b", "type": "concept", "title": "Flavor integration"}, {"id": "8b9246a6-fc49-4655-a40a-395721297871", "type": "concept", "title": "Synesthesia"}], "description": "Cross-modal effects show that perception in one sense can change what is experienced in another."}, {"id": "4db180e4-c246-4d6d-9068-8c791cafb08b", "type": "subtopic", "title": "Constancy Across Change", "children": [{"id": "491a2c14-3ddd-4285-8446-bb3917893e69", "type": "concept", "title": "Color constancy"}, {"id": "79f6d8df-0bd3-4d6c-a828-2f6d813b8fdd", "type": "concept", "title": "Size constancy"}, {"id": "09403fb3-ba8d-4e98-92d4-ce4740f31cfd", "type": "concept", "title": "Object constancy"}, {"id": "829ead85-5811-48c6-9d48-d57fa5e2b103", "type": "concept", "title": "Speech constancy"}], "description": "Constancy allows stable perception despite changes in illumination, viewpoint, motion, and sensory noise."}]}, {"id": "24d013d1-365a-4ed7-8a60-cbfa3d9fa1bf", "type": "topic", "title": "Illusions, Disorders, Development, Culture, and Individual Differences", "description": "Use illusions, atypical perception, lifespan change, and culture to reveal how perceptual systems work.", "children": [{"id": "c09c917b-866a-497a-b714-c38bf9b28d6e", "type": "subtopic", "title": "Perceptual Illusions", "children": [{"id": "c63024e8-3836-43f5-ae0d-85b1b7753ade", "type": "concept", "title": "Geometric illusions"}, {"id": "819e8847-8482-4330-8f27-484774a758b0", "type": "concept", "title": "Motion illusions"}, {"id": "f089dff4-bfc6-4c82-a5ce-73ce0bf5a9d2", "type": "concept", "title": "Color illusions"}, {"id": "761749d9-32d7-40d5-974e-d75a75b1b715", "type": "concept", "title": "Auditory illusions"}], "description": "Illusions are useful tools because they reveal the assumptions and shortcuts used by perceptual systems."}, {"id": "015f03e4-c46d-4353-8b84-6979939d28bb", "type": "subtopic", "title": "Perceptual Disorders", "children": [{"id": "5419a785-5ecf-4a97-8787-a5532984121d", "type": "concept", "title": "Agnosia"}, {"id": "eb6bf40b-ba54-45a3-a517-574cd97e0b9b", "type": "concept", "title": "Prosopagnosia"}, {"id": "790c92ec-4723-4c07-b3bd-1c43bdd7b8a7", "type": "concept", "title": "Neglect"}, {"id": "58a1201f-cd79-4576-98ff-54c1ea67c4de", "type": "concept", "title": "Synesthesia and atypical perception"}], "description": "Disorders show how specific perceptual processes can break down after injury, development, or disease."}, {"id": "3cc9607b-5bb4-4dbd-aa88-776e37c47eb5", "type": "subtopic", "title": "Development, Culture, and Individual Differences", "children": [{"id": "32933621-48d8-4868-b410-215fdea94657", "type": "concept", "title": "Infant perception"}, {"id": "af045531-f436-476a-8eb6-d8758c8e24db", "type": "concept", "title": "Aging and sensory loss"}, {"id": "716fd799-5489-44d5-9d23-0a46db13e378", "type": "concept", "title": "Cultural scene perception"}, {"id": "a8d17930-1fb2-4539-a591-364d6b367a60", "type": "concept", "title": "Neurodiversity and accessibility"}], "description": "Perception changes across the lifespan and varies with culture, experience, training, and sensory ability."}]}, {"id": "963ebf6e-5f37-489d-8742-47a6f8433d3d", "type": "topic", "title": "Contemporary Models, Applications, Ethics, and Capstone Perception Project", "description": "Synthesize perception through computational models, applied domains, ethical issues, and a final demonstration or research design.", "children": [{"id": "6e9ed017-9ac0-4d2c-8e77-e843b7fa8cfd", "type": "subtopic", "title": "Computational and AI Models", "children": [{"id": "af07e1fa-d45a-4b05-a9c2-2bc4ac297b81", "type": "concept", "title": "Bayesian models"}, {"id": "b62d81a1-96f4-4cd9-9ac9-71b018c0f200", "type": "concept", "title": "Deep neural networks"}, {"id": "15086bc4-66b8-47c3-96ca-8c9b82e386fd", "type": "concept", "title": "Computer vision comparisons"}, {"id": "f8450442-e231-46e8-b990-44bcc5e9faaa", "type": "concept", "title": "Model interpretability"}], "description": "Computational models help test theories of perception, but they also reveal differences between machines and humans."}, {"id": "ad49a700-ec3f-4615-8f92-da59dce774d6", "type": "subtopic", "title": "Applied Perception", "children": [{"id": "66ced7fc-eb84-4204-8e69-41a1656ebc51", "type": "concept", "title": "Interface design"}, {"id": "316fdf5e-8171-4acc-9596-8bdf5596b913", "type": "concept", "title": "Warning signals"}, {"id": "f5378497-7ab7-486f-af16-801e41ef3c10", "type": "concept", "title": "Clinical assessment"}, {"id": "20ce28d1-4788-4070-833d-17d91370a34e", "type": "concept", "title": "Augmented and virtual reality"}], "description": "Perception science informs design, safety, medicine, media, human factors, education, and accessibility."}, {"id": "4a573df4-49de-4fa6-876e-c644c788ed8c", "type": "subtopic", "title": "Capstone Project", "children": [{"id": "844ed738-a2d8-4f4c-8c20-aae178b76f94", "type": "concept", "title": "Research question"}, {"id": "3d9f866c-5d8e-44c8-bd5a-f83aeae3995f", "type": "concept", "title": "Demonstration or experiment"}, {"id": "a00e277a-ab44-454f-bb8e-3ec0ee96fdc6", "type": "concept", "title": "Measurement plan"}, {"id": "455a3a87-ff35-4592-98c7-9ac6020f2aab", "type": "concept", "title": "Ethics and accessibility reflection"}], "description": "The capstone asks students to explain, demonstrate, or test a perceptual phenomenon with scientific and ethical care."}]}], "dbBacked": true}$senpjson$::jsonb,
